import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"艮下离上 旅：","description":"京氏易传 - 艮下离上 旅：","frontmatter":{"title":"艮下离上 旅：","description":"京氏易传 - 艮下离上 旅："},"headers":[],"relativePath":"zh/classics/jingshi/051.md","filePath":"zh/classics/jingshi/051.md"}'),i={name:"zh/classics/jingshi/051.md"};function r(c,a,o,p,d,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"艮下离上-旅",tabindex:"-1"},[l("艮下离上 旅： "),e("a",{class:"header-anchor",href:"#艮下离上-旅","aria-label":"Permalink to “艮下离上 旅：”"},"​")],-1),e("p",null,"阴中见阳，荡入阳中。阴阳二气交互，见本象。火居山上，为旅之义。【离为阴，初九为阳；艮为阳，初六为阴。二气交互，上下见木也。火在上，无止象，旅之义。】《易》曰：“旅人先笑后号咷”。又曰：“得其资斧”。仲尼为旅人，固可知矣。【旅卦为取象，火在山上显露无止，五行入卦消息，去此迁也。】与艮为飞伏。【丙辰土，己卯木。】其居初六元士，九四诸侯见应。",-1),e("p",null,"建始己酉至甲寅，【秋分，立春。】积算起甲寅至癸丑，周而复始。火土木入离艮。【火木土入卦起积算。】",-1),e("p",null,"五星从位起荧惑，【火星入卦见本象。】壁宿从位降丙辰，【二十八宿，壁宿入旅卦初六丙辰土位上起算。】分气候三十六。【分三十六数起卦推算。】",-1),e("p",null,"火土同宫，二气合应，阴阳相对，吉凶分乎阴位。上九阳居宗庙，得丧于易。六五为卦之主，不系于一凶，其宜也。",-1),e("p",null,"内象适变，荡阴入阳，巽顺于外，进退意器，外象明，应内，为鼎。次降火从风入鼎。【初九之初六，六二之九二，巽为风，离象火，曰鼎。】",-1)])])}const _=s(i,[["render",r]]);export{u as __pageData,_ as default};
